package com.travelbird.ai.service;
import com.travelbird.ai.dto.request.*;import com.travelbird.ai.dto.response.*;import com.travelbird.ai.entity.*;import com.travelbird.ai.repository.*;import com.travelbird.global.error.*;import com.travelbird.place.repository.PlaceRepository;import com.travelbird.trip.service.TripAiRouteService;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AiPreviewService{public static final String MANUAL_PLACE_REASON="사용자가 일정 미리보기에 직접 추가한 장소입니다.";private final AiTripPreviewRepository previews;private final AiPreviewRouteMutationRepository routeMutations;private final PlaceRepository places;private final TripAiRouteService trips;private final Clock clock;public AiPreviewService(AiTripPreviewRepository p,AiPreviewRouteMutationRepository routeMutations,PlaceRepository places,TripAiRouteService trips,Clock c){previews=p;this.routeMutations=routeMutations;this.places=places;this.trips=trips;clock=c;}@Transactional(readOnly=true)public AiPreviewResponse get(Long uid,Long id){return response(require(previews.findDetail(id).orElse(null),uid));}@Transactional public AiPreviewResponse update(Long uid,Long id,UpdateAiTripPreviewRequest r){var p=require(previews.findByIdForGate(id).orElse(null),uid);if(r==null||r.version()==null||r.hasExplicitNull())throw new BusinessException(ErrorCode.INVALID_REQUEST);if(r.version()!=p.getVersion())throw new BusinessException(ErrorCode.AI_PREVIEW_MODIFICATION_CONFLICT);List<AiPreviewDay> route=null;if(r.days()!=null){validatePatch(r.days(),p.getJob());var oldReasons=new HashMap<Long,String>();p.getDays().forEach(d->d.getPlaces().forEach(x->oldReasons.put(x.getPlace().getId(),x.getReason())));route=new ArrayList<>();for(var rd:r.days()){var d=new AiPreviewDay(rd.day());for(var rp:rd.places()){var place=places.findById(rp.placeId()).orElseThrow(()->new BusinessException(ErrorCode.PLACE_NOT_FOUND));d.add(new AiPreviewPlace(place,rp.order(),oldReasons.getOrDefault(rp.placeId(),MANUAL_PLACE_REASON)));}route.add(d);}}if(r.hashtags()!=null&&(r.hashtags().stream().anyMatch(x->x==null||x.length()>10)||new HashSet<>(r.hashtags()).size()!=r.hashtags().size()))throw new BusinessException(ErrorCode.INVALID_REQUEST);if(route!=null){routeMutations.stageOrders(id);p.reconcileRoute(route,LocalDateTime.now(clock));}p.replace(r.tripTitle(),r.summary(),r.hashtags(),null,LocalDateTime.now(clock));previews.flush();return response(p);}@Transactional public ApplyAiPreviewResponse apply(Long uid,Long id){var p=require(previews.findByIdForGate(id).orElse(null),uid);if(p.getAppliedTrip()!=null)return new ApplyAiPreviewResponse(p.getAppliedTrip().getId(),p.getJob().getTargetTripId()==null?"CREATED_NEW_TRIP":"UPDATED_EXISTING_TRIP",p.getAppliedAt());var result=trips.apply(p,uid);p.applied(result.trip(),result.at());return new ApplyAiPreviewResponse(result.trip().getId(),result.type(),result.at());}@Transactional public void makePermanent(Long uid,Long id){require(previews.findByIdForGate(id).orElse(null),uid).makePermanent(LocalDateTime.now(clock));}@Transactional public void makeTemporary(Long uid,Long id){require(previews.findByIdForGate(id).orElse(null),uid).makeTemporary(LocalDateTime.now(clock));}
 private AiTripPreview require(AiTripPreview p,Long uid){if(p==null)throw new BusinessException(ErrorCode.AI_PREVIEW_NOT_FOUND);if(!p.ownedBy(uid))throw new BusinessException(ErrorCode.AI_PREVIEW_ACCESS_DENIED);if(p.expired(LocalDateTime.now(clock)))throw new BusinessException(ErrorCode.AI_PREVIEW_EXPIRED);return p;}private void validatePatch(List<UpdateAiPreviewDayRequest> days,AiRecommendationJob job){int maxDay=(int)java.time.temporal.ChronoUnit.DAYS.between(job.getStartDate(),job.getEndDate())+1;var ids=new HashSet<Long>();var dayIds=new HashSet<Integer>();for(var d:days){if(d==null||d.day()==null||d.day()<1||d.day()>maxDay||!dayIds.add(d.day())||d.places()==null)throw new BusinessException(ErrorCode.INVALID_AI_PREVIEW_ROUTE);if(d.places().size()>15)throw new BusinessException(ErrorCode.AI_PREVIEW_DAY_PLACE_LIMIT_EXCEEDED);var orders=new HashSet<Integer>();for(var p:d.places()){if(p==null||p.placeId()==null||p.order()==null||p.order()<1||!orders.add(p.order()))throw new BusinessException(ErrorCode.INVALID_AI_PREVIEW_ROUTE);if(!ids.add(p.placeId()))throw new BusinessException(ErrorCode.AI_PREVIEW_PLACE_DUPLICATED);}for(int i=1;i<=d.places().size();i++)if(!orders.contains(i))throw new BusinessException(ErrorCode.INVALID_AI_PREVIEW_ROUTE);}}
 private AiPreviewResponse response(AiTripPreview p){return new AiPreviewResponse(p.getId(),p.getRetentionStatus(),true,p.getTripTitle(),p.getSummary(),new ArrayList<>(p.getHashtags()),p.getDays().stream().map(d->new AiPreviewDayResponse(d.getDayNumber(),d.getPlaces().stream().map(x->new AiPreviewPlaceResponse(x.getPlace().getId(),x.getVisitOrder(),x.getReason())).toList())).toList(),p.getCreatedAt(),p.getUpdatedAt(),p.getExpiresAt(),p.getSavedAt(),p.getVersion());}}
